// Static NBA reference data (generated by scripts/build-data.mjs). Server-side helpers; client
// components receive the compact option lists they need as props.
import coachesFile from '@/data/coaches.json'
import playersFile from '@/data/players.json'
import { TEAMS } from '@/data/teams'
import type { AnswerKind, Coach, Player, Team, TeamAbbr } from './types'
import { teamAnswerValid } from './validation'

export const PLAYERS: Player[] = playersFile.players as Player[]
export const COACHES: Coach[] = coachesFile.coaches as Coach[]
export const DATA_GENERATED_AT: string = playersFile.generatedAt

export const TEAM_BY_ABBR: Record<TeamAbbr, Team> = Object.fromEntries(TEAMS.map((t) => [t.abbr, t]))
export const TEAM_BY_ESPN_ID: Record<string, Team> = Object.fromEntries(TEAMS.map((t) => [t.espnId, t]))
export const PLAYER_BY_ID: Record<string, Player> = Object.fromEntries(PLAYERS.map((p) => [p.id, p]))
export const COACH_BY_ID: Record<string, Coach> = Object.fromEntries(COACHES.map((c) => [c.id, c]))

/** Validates an answer id for a question kind (used by the server before saving). */
export function answerLookup(kind: AnswerKind, id: string): boolean {
  const team = teamAnswerValid(kind, id)
  if (team !== null) return team
  if (kind === 'coach') return Object.hasOwn(COACH_BY_ID, id)
  if (kind === 'rookie') return Object.hasOwn(PLAYER_BY_ID, id) && PLAYER_BY_ID[id].rookie === true
  return Object.hasOwn(PLAYER_BY_ID, id)
}

/** Human label for an answer id of a given kind ("Victor Wembanyama (SAS)", "Spurs"…). */
export function answerLabel(kind: AnswerKind, id: string | null | undefined): string {
  if (!id) return '—'
  if (kind === 'coach') {
    const c = COACH_BY_ID[id]
    return c ? `${c.name} (${c.team})` : `Coach #${id}`
  }
  if (kind === 'player' || kind === 'rookie') {
    const p = PLAYER_BY_ID[id]
    return p ? `${p.name} (${p.team})` : `Joueur #${id}`
  }
  return TEAM_BY_ABBR[id]?.name ?? id
}

/** Compact option shape sent to client pickers. */
export interface PickerOption {
  id: string
  label: string
  sub: string // team · position, or conference
  rookie?: boolean
}

export function playerOptions(rookiesOnly = false): PickerOption[] {
  return PLAYERS.filter((p) => !rookiesOnly || p.rookie).map((p) => ({
    id: p.id,
    label: p.name,
    sub: [p.team, p.pos].filter(Boolean).join(' · '),
    rookie: p.rookie,
  }))
}

export function coachOptions(): PickerOption[] {
  return COACHES.map((c) => ({ id: c.id, label: c.name, sub: TEAM_BY_ABBR[c.team]?.name ?? c.team }))
}

export function teamOptions(conf?: 'E' | 'W'): PickerOption[] {
  return TEAMS.filter((t) => !conf || t.conference === conf).map((t) => ({
    id: t.abbr,
    label: t.name,
    sub: t.conference === 'E' ? 'Est' : 'Ouest',
  }))
}
